// lib/ml/mind_classifier.dart
//
// Pure-Dart TF-IDF + Logistic Regression classifier.
// Loads mind_model.json from assets (generated by ml/train_baseline.py).
//
// Scoring pipeline:
//   raw text → char n-gram TF-IDF → LR softmax → per-message prob
//   + exponential moving average over 30 min
//   medium ≥ 0.5 | high ≥ 0.8 + 2 hits in 10 min

import 'dart:convert';
import 'dart:math' as math;
import 'package:flutter/services.dart';

enum MindRisk { safe, medium, high }

class MindResult {
  final MindRisk risk;
  final double probability;   // probability of the concern/high class
  final String label;         // "safe" | "concern" | "high"

  const MindResult({required this.risk, required this.probability, required this.label});
}

class MindClassifier {
  MindClassifier._();
  static final MindClassifier instance = MindClassifier._();

  // Model weights (loaded once)
  Map<String, int>? _vocab;      // token → column index
  List<double>? _idf;            // idf[col]
  List<List<double>>? _coef;     // coef[class][col]
  List<double>? _intercept;      // intercept[class]
  List<String>? _classes;        // ["safe","concern","high"]

  bool get isLoaded => _vocab != null;

  // EMA state
  double _ema = 0.0;
  final double _emaAlpha = 0.3;   // decay factor
  DateTime _lastUpdate = DateTime.fromMillisecondsSinceEpoch(0);

  // 10-min high-risk counter
  final List<DateTime> _highHits = [];

  // ── Initialisation ─────────────────────────────────────────────────────────

  Future<void> load() async {
    if (isLoaded) return;
    try {
      final raw = await rootBundle.loadString('assets/mind_model.json');
      final data = json.decode(raw) as Map<String, dynamic>;

      _vocab = (data['vocab'] as Map<String, dynamic>).map(
        (k, v) => MapEntry(k, v as int),
      );
      _idf = (data['idf'] as List).map((e) => (e as num).toDouble()).toList();
      _coef = (data['coef'] as List)
          .map((row) => (row as List).map((e) => (e as num).toDouble()).toList())
          .toList();
      _intercept = (data['intercept'] as List).map((e) => (e as num).toDouble()).toList();
      _classes = (data['classes'] as List).map((e) => e as String).toList();
    } catch (e) {
      // Model asset not yet generated — fail gracefully
      _vocab = {};
      _idf = [];
      _coef = [];
      _intercept = [];
      _classes = ['safe', 'concern', 'high'];
    }
  }

  // ── Inference ──────────────────────────────────────────────────────────────

  MindResult classify(String text) {
    if (!isLoaded || _vocab!.isEmpty) {
      return const MindResult(risk: MindRisk.safe, probability: 0.0, label: 'safe');
    }

    final tfidf = _tfidfVector(text);
    final scores = _logits(tfidf);
    final probs = _softmax(scores);

    // Probability of "concern" + "high" combined
    final concernIdx = _classes!.indexOf('concern');
    final highIdx = _classes!.indexOf('high');
    final riskProb = (concernIdx >= 0 ? probs[concernIdx] : 0.0) +
        (highIdx >= 0 ? probs[highIdx] : 0.0);

    final labelIdx = probs.indexOf(probs.reduce(math.max));
    final label = _classes![labelIdx];

    return _applyEmaAndRules(riskProb, label);
  }

  // ── Private helpers ────────────────────────────────────────────────────────

  List<double> _tfidfVector(String text) {
    final size = _vocab!.length;
    final tf = List<double>.filled(size, 0.0);
    final ngrams = _charNgrams(text.toLowerCase(), 1, 3);
    if (ngrams.isEmpty) return tf;

    for (final ng in ngrams) {
      final idx = _vocab![ng];
      if (idx != null) tf[idx] += 1.0;
    }

    // TF-IDF
    for (int i = 0; i < size; i++) {
      if (tf[i] > 0) tf[i] = (1 + math.log(tf[i])) * _idf![i];
    }

    // L2 normalise
    final norm = math.sqrt(tf.fold(0.0, (s, x) => s + x * x));
    if (norm > 0) {
      for (int i = 0; i < size; i++) tf[i] /= norm;
    }
    return tf;
  }

  List<String> _charNgrams(String text, int minN, int maxN) {
    final result = <String>[];
    for (int n = minN; n <= maxN; n++) {
      for (int i = 0; i <= text.length - n; i++) {
        result.add(text.substring(i, i + n));
      }
    }
    return result;
  }

  List<double> _logits(List<double> x) {
    return List.generate(_coef!.length, (c) {
      double dot = _intercept![c];
      for (int i = 0; i < x.length; i++) {
        dot += _coef![c][i] * x[i];
      }
      return dot;
    });
  }

  List<double> _softmax(List<double> logits) {
    final maxL = logits.reduce(math.max);
    final exps = logits.map((l) => math.exp(l - maxL)).toList();
    final sum = exps.reduce((a, b) => a + b);
    return exps.map((e) => e / sum).toList();
  }

  MindResult _applyEmaAndRules(double prob, String label) {
    final now = DateTime.now();
    final minutesSinceLast = now.difference(_lastUpdate).inMinutes;

    // Decay EMA if more than 30 minutes since last message
    if (minutesSinceLast > 30) _ema = 0.0;
    _ema = _emaAlpha * prob + (1 - _emaAlpha) * _ema;
    _lastUpdate = now;

    // Track high-risk hits in the last 10 min
    _highHits.removeWhere((t) => now.difference(t).inMinutes > 10);
    if (_ema >= 0.8) _highHits.add(now);

    final MindRisk risk;
    if (_ema >= 0.8 && _highHits.length >= 2) {
      risk = MindRisk.high;
    } else if (_ema >= 0.5) {
      risk = MindRisk.medium;
    } else {
      risk = MindRisk.safe;
    }

    return MindResult(risk: risk, probability: _ema, label: label);
  }
}
